false&#34;&gt;&lt;mrow&gt;&lt;mi&gt;Z&lt;/mi&gt;&lt;mo&gt;&amp;#x2208;&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;mi&gt;X&lt;/mi&gt;&lt;/msub&gt;&lt;msub&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;S&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;t&lt;/mi&gt;&lt;/mrow&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;n&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;/mstyle&gt;&lt;/mtd&gt;&lt;/mtr&gt;&lt;/mtable&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\begin{array}{ccc}
\hat Z\in\mathcal H_{I_n}
&amp;amp;\xrightarrow{\mathrm dL_Q}&amp;amp;
Q\hat Z\in\mathcal H_Q\\[2mm]
{\scriptstyle\mathrm d\pi_{I_n}}\!\downarrow
&amp;amp;&amp;amp;
\downarrow\!{\scriptstyle\mathrm d\pi_Q}\\[2mm]
Z_0\in T_{X_0}\mathrm{St}_p(n)
&amp;amp;\xrightarrow{\mathrm d(Q\mathbin{\cdot})_{X_0}}&amp;amp;
