&lt;h2 id=&#34;&amp;#x5171;&amp;#x8F6D;&amp;#x53D8;&amp;#x6362;&amp;#x4E0E;&amp;#x5171;&amp;#x8F6D;&amp;#x51FD;&amp;#x6570;&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#&amp;#x5171;&amp;#x8F6D;&amp;#x53D8;&amp;#x6362;&amp;#x4E0E;&amp;#x5171;&amp;#x8F6D;&amp;#x51FD;&amp;#x6570;&#34;&gt;#&lt;/a&gt; &amp;#x5171;&amp;#x8F6D;&amp;#x53D8;&amp;#x6362;&amp;#x4E0E;&amp;#x5171;&amp;#x8F6D;&amp;#x51FD;&amp;#x6570;&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;Fenchel &amp;#x5171;&amp;#x8F6D;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;mo&gt;&amp;#x2217;&lt;/mo&gt;&lt;/msup&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;munder&gt;&lt;mrow&gt;&lt;mi&gt;sup&lt;/mi&gt;&lt;mo&gt;&amp;#x2061;&lt;/mo&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;&amp;#x2208;&lt;/mo&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;d&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;o&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;m&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;f&lt;/mi&gt;&lt;/mrow&gt;&lt;/mrow&gt;&lt;/munder&gt;&lt;mrow&gt;&lt;mo fence=&#34;true&#34;&gt;{&lt;/mo&gt;&lt;msup&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;/msup&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;&amp;#x2212;&lt;/mo&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo fence=&#34;true&#34;&gt;}&lt;/mo&gt;&lt;/mrow&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;f^*(y)  = \sup_{x\in \mathrm{dom f}} \left\{ y^T x - f(x)\right\}
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10764em;&#34;&gt;f&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.7387em;&#34;&gt;&lt;span style=&#34;top:-3.113em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mbin mtight&#34;&gt;&amp;#x2217;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.8652em;vertical-align:-0.9739em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop op-limits&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.4306em;&#34;&gt;&lt;span style=&#34;top:-2.1535em;margin-left:0em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;mrel mtight&#34;&gt;&amp;#x2208;&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathrm mtight&#34; style=&#34;margin-right:0.07778em;&#34;&gt;domf&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span&gt;&lt;span class=&#34;mop&#34;&gt;sup&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;&amp;#x200B;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.9739em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;minner&#34;&gt;&lt;span class=&#34;mopen delimcenter&#34; style=&#34;top:0em;&#34;&gt;&lt;span class=&#34;delimsizing size1&#34;&gt;{&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8913em;&#34;&gt;&lt;span style=&#34;top:-3.113em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;T&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;&amp;#x2212;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10764em;&#34;&gt;f&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mclose delimcenter&#34; style=&#34;top:0em;&#34;&gt;&lt;span class=&#34;delimsizing size1&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;Fenchel&amp;#x5171;&amp;#x8F6D;&amp;#x8BF4;&amp;#x660E;&amp;#x4E00;&amp;#x4E2A;&amp;#x6620;&amp;#x5C04;&amp;#x7684;&amp;#x5BF9;&amp;#x5076;&amp;#x4FE1;&amp;#x606F;&amp;#x7B49;&amp;#x4EF7;&amp;#x4E8E;&amp;#x5176;&amp;#x659C;&amp;#x7387;&amp;#x5BF9;&amp;#x5E94;&amp;#x7684;&amp;#x6700;&amp;#x4F18;&amp;#x652F;&amp;#x6491;&amp;#x659C;&amp;#x7387;&amp;#x7684;&amp;#x4FE1;&amp;#x606F;&amp;#x3002;&lt;/p&gt;
&lt;p&gt;&amp;#x4E8B;&amp;#x5B9E;&amp;#x4E0A;&amp;#xFF0C;&amp;#x6839;&amp;#x636E;Fenchel&amp;#x2013;Moreau &amp;#x5B9A;&amp;#x7406;&amp;#xFF0C;&amp;#x5BF9;&amp;#x4E8E;&amp;#x95ED;&amp;#x51F8;&amp;#x51FD;&amp;#x6570;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;f&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8889em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10764em;&#34;&gt;f&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&amp;#xFF0C; &amp;#x6EE1;&amp;#x8DB3;&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;mrow&gt;&lt;mo&gt;&amp;#x2217;&lt;/mo&gt;&lt;mo&gt;&amp;#x2217;&lt;/mo&gt;&lt;/mrow&gt;&lt;/msup&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;f&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;f^{**} = f
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.9331em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10764em;&#34;&gt;f&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.7387em;&#34;&gt;&lt;span style=&#34;top:-3.113em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&amp;#x2217;&amp;#x2217;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8889em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.10764em;&#34;&gt;f&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Legendre &amp;#x53D8;&amp;#x6362;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Legendre-Type Function&lt;/strong&gt;&lt;/p&gt;
&lt;section class=&#34;post-bibliography&#34;&gt;&lt;h1 class=&#34;post-bibliography-title&#34; id=&#34;references&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#references&#34;&gt;&lt;span&gt;#&lt;/span&gt;&lt;/a&gt; &amp;#x53C2;&amp;#x8003;&amp;#x6587;&amp;#x732E;&lt;/h1&gt;&lt;div class=&#34;csl-bib-body&#34;&gt;  &lt;div data-csl-entry-id=&#34;wen25optbook02&#34; class=&#34;csl-entry&#34; id=&#34;ref-wen25optbook02&#34;&gt;
    &lt;div class=&#34;csl-left-margin&#34;&gt;1. &lt;/div&gt;&lt;div class=&#34;csl-right-inline&#34;&gt;&amp;#x6587;&amp;#x518D;&amp;#x6587;. &amp;#x300A;&amp;#x5927;&amp;#x6570;&amp;#x636E;&amp;#x5206;&amp;#x6790;&amp;#x4E2D;&amp;#x7684;&amp;#x7B97;&amp;#x6CD5;&amp;#x300B;&amp;#x2013; &amp;#x51F8;&amp;#x96C6; [Internet]. &amp;#x5317;&amp;#x4EAC;&amp;#x5927;&amp;#x5B66;&amp;#x5317;&amp;#x4EAC;&amp;#x56FD;&amp;#x9645;&amp;#x6570;&amp;#x5B66;&amp;#x7814;&amp;#x7A76;&amp;#x4E2D;&amp;#x5FC3;; [cited 2026 Sep 23]. Available from: &lt;a href=&#34;http://faculty.bicmr.pku.edu.cn/~wenzw/optbook/lect/02-convex-set.pdf&#34;&gt;http://faculty.bicmr.pku.edu.cn/~wenzw/optbook/lect/02-convex-set.pdf&lt;/a&gt; &lt;span class=&#34;citation-backrefs&#34;&gt;&lt;a class=&#34;citation-backref&#34; href=&#34;#cite-wen25optbook02-1&#34; aria-label=&#34;&amp;#x8FD4;&amp;#x56DE;&amp;#x6B63;&amp;#x6587;&amp;#x5F15;&amp;#x7528; 1&#34;&gt;&amp;#x21A9;&lt;/a&gt;&lt;/span&gt;&lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;&lt;/section&gt;

 &lt;link rel=&#34;stylesheet&#34; type=&#34;text/css&#34; href=&#34;https://cdn.jsdelivr.net/hint.css/2.4.1/hint.min.css&#34;&gt;&lt;h1 id=&#34;从-tabaco-到烟草和煙草たばこ&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#从-tabaco-到烟草和煙草たばこ&#34;&gt;#&lt;/a&gt; 从 tabaco 到”烟草”和「煙草（たばこ）」&lt;/h1&gt;
&lt;p&gt;只看字形的话，中文”烟草”和日语「煙草」像是同一个汉字词在两地各自保留了下来。但把读音也放进来，事情就不一样了——它们其实是两条完全不同的词汇史，碰巧在同一个字形上交会。&lt;/p&gt;
&lt;p&gt;中文的”烟草”，是把外来物重新命名为透明的汉语复合词。”淡巴菰 / 淡巴枯 / 淡把姑”这些早期音译并没有音变成 yancao，而是直接被”烟 + 草”这个语义更清楚的名字替换掉了。&lt;/p&gt;
&lt;p&gt;日语的「たばこ」则是南蛮贸易时期进来的外来词，通常认为来自葡萄牙语或西班牙语的 tabaco。后来虽然写成了「煙草 / 莨」等汉字，读音却原样保留了下来。所以它不是逐字读成「けむり + くさ」，也不是按音读读成「えんそう」。&lt;/p&gt;
&lt;p&gt;也就是说，中日同用”烟草 / 煙草”这组字，不等于它们继承了同一个”汉语读音”。中文把词改造成了汉语内部的形态；日语把汉字当作意义标签，贴在了已经流通的外来读音上。&lt;/p&gt;
&lt;h2 id=&#34;一条大航海时代的传播线&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#一条大航海时代的传播线&#34;&gt;#&lt;/a&gt; 一条大航海时代的传播线&lt;/h2&gt;
&lt;p&gt;烟草原产美洲。欧洲人接触它之后，西班牙语 tabaco、葡萄牙语 tabaco 这类名称随殖民贸易扩散开来。Online Etymology Dictionary 把英语 tobacco 追到西班牙语 tabaco，同时指出这个词通常被认为至少部分来自加勒比阿拉瓦克语族，可能是泰诺语里指烟叶卷或吸烟管的名称。&lt;/p&gt;
&lt;p&gt;东亚这边的关键中转站是菲律宾与南海贸易。16 世纪后期，西班牙人在菲律宾经营马尼拉-阿卡普尔科帆船贸易，美洲作物和美洲白银一起进了亚洲贸易网。日本”たばこと塩の博物館”在介绍大航海时代时，也把烟草列在从新大陆经欧洲扩散到世界各地的物产当中。进入日本的路径一般放在南蛮贸易背景下讨论：1543 年葡萄牙人漂到种子岛以后，九州港口逐渐卷入日欧贸易，烟草也作为南蛮渡来的珍物进入日本。&lt;/p&gt;
&lt;p&gt;日本这边，确切的早期记录集中在 16 世纪末到 17 世纪初。JTI 年表列出，1601 年方济各会士向德川家康献上烟草叶和种子；1605 年左右已有禁烟、禁买卖、禁耕作的记录。博物馆的”江户时代的たばこ文化”也说，日本在 16 世纪末以后传入烟草，吸烟习惯扩散，国内开始种植，幕府随即以风纪、火灾、粮食生产等理由多次禁烟。&lt;/p&gt;
&lt;p&gt;中国这边，传入时间也大致在明末万历年间。烟草约在 16 世纪末、万历年间传入，最早音译名是”淡巴枯”，明末改用”烟草”。日本 y-history 的”タバコ”条目在”中國と日本のタバコ”部分整理了几种传入路线：菲律宾到福建、东南亚海路到广东、日本经朝鲜到辽东、印度支那内陆到云南等。史料上以福建、广东路线较多，并提到万历末年”淡把姑”传入福建的说法。&lt;/p&gt;
&lt;p&gt;可见，烟草进入东亚走的不是一条单纯的”中文词传给日文”路线，而是伴随海商、传教士、南蛮贸易、菲律宾贸易网、东南亚贸易网，在多个港口同时扩散。物和名字都带着外来性，但每种语言给它安家的方式不一样。&lt;/p&gt;
&lt;h2 id=&#34;中文从音译名到语义名&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#中文从音译名到语义名&#34;&gt;#&lt;/a&gt; 中文：从音译名到语义名&lt;/h2&gt;
&lt;p&gt;明清材料里，烟草有一串不稳定的名字：淡巴菰、淡巴枯、淡把姑、淡巴菇、担不归、金丝烟、芬草等等。这些名字大致分两类。&lt;/p&gt;
&lt;p&gt;一类是音译，围绕 tabaco 的声音做汉字拟音。”淡巴菰 / 淡巴枯 / 淡把姑”都在模拟 ta-ba-co 一类的音节。因为它从吕宋、福建、广东、东南亚等多口岸进入，又经过不同方言和书写者记录，字形不统一是自然的事。&lt;/p&gt;
&lt;p&gt;另一类是语义命名。”金丝烟”偏向加工形态——烟叶切成细丝；”烟草 / 菸草”则抓住了最核心的两个可见特征：草本植物，使用时产生烟。这个名字不需要知道它从哪里来，也不需要知道 tabaco 怎么发音，第一次看到也大概能猜到是什么东西。&lt;/p&gt;
&lt;p&gt;“淡巴菰”没有发展成现代通用名，不是因为读音不够接近，而是它不适合当普通汉语词：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;音译字形不稳定。”菰、枯、姑、菇”只是借音字，很难形成统一的书写规范。&lt;/li&gt;
&lt;li&gt;语义信息太少。普通读者看到”淡巴菰”没法从字面猜出用途；看到”烟草”马上能建立类别。&lt;/li&gt;
&lt;li&gt;物品本土化以后，外来名的必要性自然下降。烟草很快在福建、广东、江南、北方军镇等地流行并种植，不再是单纯的”番货”，而是日常消费品和经济作物。&lt;/li&gt;
&lt;li&gt;汉语构词偏好双音节、可组合、可派生的语素结构。”烟草”可以自然派生出烟叶、烟丝、烟袋、烟枪、抽烟、禁烟等一群词；”淡巴菰”很难进入这个网络。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;所以中文这里发生的，不是”音译词音变为原始汉语读音”，而是一次词汇替换：早期外来音译词被本土语义复合词取代。现代汉语读 yancao，是因为这个词已经是”烟 + 草”，不是因为 ta-ba-co 在汉语音系里一步步演化出了 yan-cao。&lt;/p&gt;
&lt;h2 id=&#34;日语外来读音先固定汉字后来表义&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#日语外来读音先固定汉字后来表义&#34;&gt;#&lt;/a&gt; 日语：外来读音先固定，汉字后来表义&lt;/h2&gt;
&lt;p&gt;日语这边正好相反：读音「たばこ」先作为外来词固定下来，然后才配上「煙草」这个写法。&lt;/p&gt;
&lt;p&gt;Weblio 收录的《デジタル大辞泉》词条写作「タバコ【(ポルトガル)tabaco】【煙草／莨】」，读法标为「たばこ」。同一页面还列出「煙草」可有「タバコ、ケムリグサ、ケブリグサ、エンソウ」等读法。这很有意思——它说明「けむりぐさ」和「えんそう」并非不可想象，只是没有成为现代通用词里的默认读法。&lt;/p&gt;
&lt;p&gt;原因在于日语文字系统本身。日语里的汉字不只有一种读法：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;音读：来自不同历史层次的汉字音，比如「煙」读 えん，「草」读 そう。&lt;/li&gt;
&lt;li&gt;训读：用汉字表示日本固有词，比如「煙」读 けむり，「草」读 くさ。&lt;/li&gt;
&lt;li&gt;熟字训 / 义训 / 当て字这类整词读法：字形提示意义，整组字读作一个已有的词，比如「大人（おとな）」「昨日（きのう）」。外来词也常被配上汉字来写。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;「煙草（たばこ）」就属于最后这种——字形表义，读音走词项。它不是把「煙」读成 たば、「草」读成 こ；而是整组「煙草」被用来写已经存在的外来词 tabako。汉字在这里像一个意义标签：这种东西是会产生烟的草本植物；读音则沿用贸易和日常口语里早已流通的外来名。&lt;/p&gt;
&lt;p&gt;这也解释了为什么日语没有把它稳定读成「けむりくさ」。如果日本先独立观察到一种”会冒烟的草”，再用固有词造名，「けむりぐさ」也许有机会。但实际历史上，烟草是连同吸烟方式、贸易物品身份、南蛮文化气味一起进来的，名字「たばこ」本身就是新奇物的标签。等到汉字「煙草」贴上去的时候，口语词早就扎了根。&lt;/p&gt;
&lt;p&gt;至于音读「えんそう」，同样没有胜出的理由。音读通常更适合从汉文、佛典、制度、学术语汇中进来的汉字词；烟草在日本不是作为汉文概念先由读书人引入，而是作为南蛮贸易商品、吸烟风俗和种植作物进入民间生活。传播路径是”物和口头名先到”，不是”汉字词先到”。&lt;/p&gt;
&lt;h2 id=&#34;为什么两边用了相同的汉字&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#为什么两边用了相同的汉字&#34;&gt;#&lt;/a&gt; 为什么两边用了相同的汉字？&lt;/h2&gt;
&lt;p&gt;“烟 / 煙 + 草”是个非常自然的语义组合：说明使用时有烟，原料是草本植物。对汉字文化圈的书写者来说，这差不多是摆在眼前的命名方案。&lt;/p&gt;
&lt;p&gt;但同样的字形，在中日两种语言里的功能并不一样。&lt;/p&gt;
&lt;p&gt;中文里，汉字直接参与词的读音。写成”烟草”，就按汉语读作 yancao。如果想保留 tabaco 的声音，就得继续写”淡巴菰”这类音译字。两套写法竞争的时候，透明的语义词胜出。&lt;/p&gt;
&lt;p&gt;日语里，汉字和读音的关系更松。一个汉字词可以有音读、训读，也可以有整词读法；必要时还可以用假名标音。写成「煙草」并不强迫它读成「えんそう」或「けむりくさ」。所以日语能同时保留外来声音「たばこ」和汉字语义「煙草」。&lt;/p&gt;
&lt;p&gt;分歧就在这里：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;中文：外来声音让位于本土语素，词义透明化。&lt;/li&gt;
&lt;li&gt;日语：外来声音保留，汉字承担意义标注。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;早期近代东亚面对外来物的时候，大致有三种策略：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;直接音译：保留声音，比如”淡巴菰”。&lt;/li&gt;
&lt;li&gt;意译或语义重命名：保留概念，比如”烟草”。&lt;/li&gt;
&lt;li&gt;声音和汉字分工：日语里很常见，读外来词，写表义汉字，比如「煙草（たばこ）」。&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;中文不是不能音译，日语也不是不能意译。差别在于，哪一个方案在具体的社会环境里更容易被日常使用、书写规范、商业传播和文学记录共同固定下来。&lt;/p&gt;
&lt;p&gt;烟草进入中国后，很快被纳入农业、税收、禁令、医药笔记、日常交际和消费文化——“烟草”这种普通汉语词最方便扩散。烟草进入日本后，「たばこ」作为南蛮外来物的口头名称已经强势流通，汉字「煙草」没有替换它的声音，只是给了它一个可读可写、意义清楚的外衣。&lt;/p&gt;
&lt;h2 id=&#34;小结&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#小结&#34;&gt;#&lt;/a&gt; 小结&lt;/h2&gt;
&lt;p&gt;中文”烟草”和日语「煙草（たばこ）」看起来像同源词，实际上是”同字异史”。&lt;/p&gt;
&lt;p&gt;中文这边：tabaco 的音译名进入明末文献，随后被”烟草”这个本土语义复合词取代。现代读音 yancao 来自”烟”和”草”两个汉语语素。&lt;/p&gt;
&lt;p&gt;日语那边：tabaco 作为南蛮外来词「たばこ」进入口语和生活，后来才写作「煙草」。现代读音 tabako 保留的是外来词的声音，汉字只是把”会产生烟的草叶”这个意思写出来。&lt;/p&gt;
&lt;p&gt;所以问题不在于”为什么日本没有保留 煙（けむり）草（くさ）”，而在于日本从一开始保留的就不是”煙 + 草”的组合读法，是一个外来词；「煙草」只是它的汉字表记。中文则相反，最终使用的不是外来音译，而是汉语内部重新命名后的”烟草”。&lt;/p&gt;
&lt;h2 id=&#34;参考资料&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#参考资料&#34;&gt;#&lt;/a&gt; 参考资料&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Online Etymology Dictionary, “tobacco”: &lt;a href=&#34;https://www.etymonline.com/word/tobacco&#34;&gt;https://www.etymonline.com/word/tobacco&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;たばこと塩の博物館，“たばこの歴史と文化”：&lt;a href=&#34;https://www.tabashio.jp/collection/tobacco/index.html&#34;&gt;https://www.tabashio.jp/collection/tobacco/index.html&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;たばこと塩の博物館，“大航海時代”：&lt;a href=&#34;https://www.tabashio.jp/collection/tobacco/t5/index.html&#34;&gt;https://www.tabashio.jp/collection/tobacco/t5/index.html&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;たばこと塩の博物館，“江戸時代のたばこ文化：たばこの伝播と広がり”：&lt;a href=&#34;https://www.tabashio.jp/collection/tobacco/t9/index.html&#34;&gt;https://www.tabashio.jp/collection/tobacco/t9/index.html&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;たばこと塩の博物館，“水パイプ・きせる”：&lt;a href=&#34;https://www.tabashio.jp/collection/tobacco/t8/index.html&#34;&gt;https://www.tabashio.jp/collection/tobacco/t8/index.html&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;JTI，“日本の歴史 江戸期”：&lt;a href=&#34;https://www.jti.co.jp/tobacco/knowledge/society/history/japan/edo/index.html&#34;&gt;https://www.jti.co.jp/tobacco/knowledge/society/history/japan/edo/index.html&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Weblio，“煙草”：&lt;a href=&#34;https://www.weblio.jp/content/%E7%85%99%E8%8D%89&#34;&gt;https://www.weblio.jp/content/煙草&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;Weblio，“たばこ”：&lt;a href=&#34;https://www.weblio.jp/content/%E3%81%9F%E3%81%B0%E3%81%93&#34;&gt;https://www.weblio.jp/content/たばこ&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;y-history，“タバコ”：&lt;a href=&#34;https://www.y-history.net/appendix/wh1002-082_2.html&#34;&gt;https://www.y-history.net/appendix/wh1002-082_2.html&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;湖南省卫生健康委员会，“解密烟草知识”：&lt;a href=&#34;https://wjw.hunan.gov.cn/ztzl/knowledge/zthd/kyyy/kymz/201705/t20170509_4216679.html&#34;&gt;https://wjw.hunan.gov.cn/ztzl/knowledge/zthd/kyyy/kymz/201705/t20170509_4216679.html&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;

 &lt;link rel=&#34;stylesheet&#34; type=&#34;text/css&#34; href=&#34;https://cdn.jsdelivr.net/hint.css/2.4.1/hint.min.css&#34;&gt;&lt;h1 id=&#34;网络层的基本功能&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#网络层的基本功能&#34;&gt;#&lt;/a&gt; 网络层的基本功能&lt;/h1&gt;
&lt;p&gt;网络层的基本功能主要是是基于TCP/IP 协议提供主机到主机的服务。在OSI模型中，网络层可以基于虚电路服务，建立面向连接的数据传输；在TCP/IP 模型中，网络层主要建立的是无连接的数据报服务。TCP/IP 中，网络层只向上提供简单、无连接、尽最大努力交付的数据报服务，通信可靠性通过更高层传输层负责。&lt;/p&gt;
&lt;h2 id=&#34;路由器功能与转发&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#路由器功能与转发&#34;&gt;#&lt;/a&gt; 路由器功能与转发&lt;/h2&gt;
&lt;p&gt;路由器的功能包括路由选择与分组转发&lt;/p&gt;
&lt;p&gt;路由器通过动态维护路由表获取图邻域的网络拓扑变化。根据不同的路由协议能获取的图邻域大小不同，&lt;code&gt;RIP&lt;/code&gt; 协议能直接获取的邻域信息只有相邻一跳的设备信息，但是能间接获取最多15跳的拓扑信息,&lt;code&gt;OSPF&lt;/code&gt;协议人为规定了可以查看的路由控制范围。&lt;/p&gt;
&lt;p&gt;路由器通过路由表导出转发表，实现分组转发时的查找最优化&lt;/p&gt;
&lt;h2 id=&#34;虚电路服务与数据报服务&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#虚电路服务与数据报服务&#34;&gt;#&lt;/a&gt; 虚电路服务与数据报服务&lt;/h2&gt;
&lt;h3 id=&#34;虚电路&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#虚电路&#34;&gt;#&lt;/a&gt; 虚电路&lt;/h3&gt;
&lt;p&gt;虚电路服务分为三个steps: 虚电路建立、数据传输、虚电路释放&lt;/p&gt;
&lt;p&gt;虚电路的建立:  分配虚电路号VCID(virtual circuit ID), 建立后每一个中间路由都维护一个虚电路表，记录VCID与下一跳信息&lt;/p&gt;
&lt;p&gt;虚电路建立后当前逻辑连接不独立占用相应的信道，但是会固定逻辑路径与转发表状态。&lt;/p&gt;
&lt;p&gt;结束虚电路传输后拆除释放虚电路。&lt;/p&gt;
&lt;p&gt;虚电路可能是长期的，也可能是临时性的。分为&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;永久性虚电路(PVC) -- 经过预配置相关路由表，长期存在不需要临时建立连接，灵活性差&lt;br /&gt;
= 交换型虚电路(SVC) -- 按需临时建立虚电路，停止使用后释放虚电路&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;数据报&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#数据报&#34;&gt;#&lt;/a&gt; 数据报&lt;/h3&gt;
&lt;p&gt;传输报文拆分为分组后独立封装为携带完整源地址与目的地址的独立分组传输，每一个分组的传输独立选路。&lt;/p&gt;
&lt;p&gt;数据报服务的分组交换是不保序的，也不保证可靠传输与传输质量。因此具有特点:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;无连接&lt;/li&gt;
&lt;li&gt;尽最大努力交付&lt;/li&gt;
&lt;li&gt;分组携带完整地址&lt;/li&gt;
&lt;li&gt;丢包风险与排队时延&lt;/li&gt;
&lt;li&gt;适应故障能力强&lt;/li&gt;
&lt;li&gt;资源利用率高、无需占用链路资源&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;sdn&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#sdn&#34;&gt;#&lt;/a&gt; SDN&lt;/h2&gt;
&lt;p&gt;网络层可以抽象为两个逻辑平面: 数据平面与控制平面&lt;/p&gt;
&lt;p&gt;数据平面用于分组转发；控制平面用于实现路由选择与路由信息的维护&lt;/p&gt;
&lt;p&gt;软件定义网络(SDN) 将两个平面解耦，将路由的控制平面集成并提供统一的编程API，数据平面仍然分布式控制，通过Openflow 等协议将&lt;strong&gt;流表(SDN转发表)&lt;/strong&gt; 下发到数据平面&lt;/p&gt;
&lt;p&gt;SDN提供三类接口&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;北向接口 -- 面向上层应用的标准API&lt;/li&gt;
&lt;li&gt;南向接口 -- 控制器与转发器的双向通信接口，通过OpenFlow 等协议控制异构硬件，并将控制逻辑下放到数据平面&lt;/li&gt;
&lt;li&gt;东西向接口 -- 控制器集群内部的通信接口，提升控制平面的可靠性与可拓展性&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;拥塞控制&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#拥塞控制&#34;&gt;#&lt;/a&gt; 拥塞控制&lt;/h2&gt;
&lt;p&gt;链路资源被分组竞争与阻塞导致性能下降就会发生拥塞。判断网络是否拥塞的条件为&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;负载增大但是吞吐增长小，表明网络轻度拥塞&lt;/li&gt;
&lt;li&gt;负载增大但是吞吐下降，表明网络拥塞&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;拥塞控制的两种方法&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;开环控制 -- 预先考虑可能导致拥塞的因素并静态调整&lt;/li&gt;
&lt;li&gt;闭环控制 -- 检测网络运行状况并动态监测拥塞发生，使用反馈调节控制拥塞节点。&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;ipv4-协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ipv4-协议&#34;&gt;#&lt;/a&gt; IPV4 协议&lt;/h1&gt;
&lt;h2 id=&#34;ip-分组&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ip-分组&#34;&gt;#&lt;/a&gt; IP 分组&lt;/h2&gt;
&lt;p&gt;一个IP分组包含的信息可以主要分为:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;版本段&lt;/li&gt;
&lt;li&gt;首部长度字段IHL -- 首部信息指的是IP分组的指示信息部分，整段分组除了数据的部分。首部长度用于刻画首部信息的数据位长度，以&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;4&lt;/mn&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;4B&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;4&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 为基本单位，最长首部长度为&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;60&lt;/mn&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mn&gt;15&lt;/mn&gt;&lt;mo&gt;×&lt;/mo&gt;&lt;mn&gt;4&lt;/mn&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;60B = 15\times 4B&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;60&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7278em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;15&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;×&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;4&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;， 最常见的首部长度为&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;20&lt;/mn&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;20B&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;20&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;总长度 -- 占16位，表示整个IP分组的长度，以太网MTU为 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;1500&lt;/mn&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;1500B&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;1500&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;，因此总长度应该小于MTU。广域网的MTU通常小于以太网MTU，因此路由器能对IP分组再分片。分片只发送在发送端或者中间路由器上，重组只发生在目标主机上。数据段长度满足&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;总长度&lt;/mtext&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mtext&gt;首部长度&lt;/mtext&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mtext&gt;数据段长度&lt;/mtext&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\text{总长度} - \text{首部长度} = \text{数据段长度}
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.7667em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;总长度&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;首部长度&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;数据段长度&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;标识 -- 占16位，作为单个数据报的标记，目的主机根据标识识别分片的从属并组合数据报&lt;/li&gt;
&lt;li&gt;标志 -- 占3位，首位留空，MF位用于指示是否有更多分片，&lt;code&gt;MF=1&lt;/code&gt; 标识后面还有分片，&lt;code&gt;MF=0&lt;/code&gt; 标识这是最后一个分片。 DF 位表示是否可分片， &lt;code&gt;DF=0&lt;/code&gt; 表示允许分片&lt;/li&gt;
&lt;li&gt;片偏移 -- 占13位，以8B为单位。当前分块的数据段相对于整个报文的首位偏移量。整个报文以 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;8&lt;/mn&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;8B&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;8&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 为单位，因此片偏移也以 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;8&lt;/mn&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;8B&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;8&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 为单位，只有最后一个分片可以不以 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;8&lt;/mn&gt;&lt;mi&gt;B&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;8B&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;8&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.05017em;&#34;&gt;B&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 为单位。&lt;/li&gt;
&lt;li&gt;生存时间(TTL) -- 8位，用于标记分组可跳次数，以防止在网络中无限循环。TTL=0 时，路由器丢弃该分组，并报告ICMP 差错报告时间超过报文。&lt;/li&gt;
&lt;li&gt;协议 -- 8位，指出向高层交付的协议，6为TCP,17为UDP&lt;/li&gt;
&lt;li&gt;首部检验和 -- 16位&lt;/li&gt;
&lt;li&gt;源IP地址与目的IP地址 -- 各4B&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;ip地址&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ip地址&#34;&gt;#&lt;/a&gt; IP地址&lt;/h2&gt;
&lt;p&gt;IPV4的IP地址满足CIDR机制，IP地址可以表示为&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mtext&gt;IP地址&lt;/mtext&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mrow&gt;&lt;mo fence=&#34;true&#34;&gt;{&lt;/mo&gt;&lt;mtext&gt;&amp;lt;网络前缀&amp;gt;,&amp;lt;子网号&amp;gt;,&amp;lt;主机号&amp;gt;&lt;/mtext&gt;&lt;mo fence=&#34;true&#34;&gt;}&lt;/mo&gt;&lt;/mrow&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\text{IP地址} = \left\{\text{&amp;lt;网络前缀&amp;gt;,&amp;lt;子网号&amp;gt;,&amp;lt;主机号&amp;gt;} \right\}
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord&#34;&gt;IP&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;地址&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;minner&#34;&gt;&lt;span class=&#34;mopen delimcenter&#34; style=&#34;top:0em;&#34;&gt;{&lt;/span&gt;&lt;span class=&#34;mord text&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&amp;lt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;网络前缀&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&amp;gt;,&amp;lt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;子网号&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&amp;gt;,&amp;lt;&lt;/span&gt;&lt;span class=&#34;mord cjk_fallback&#34;&gt;主机号&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose delimcenter&#34; style=&#34;top:0em;&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;一个IP地址由32位二进制数构成，每8位构成一个十进制数，用点分割。比如&lt;code&gt;192.168.0.1&lt;/code&gt; 等价于&lt;code&gt;11000000.10101000.00000000.00000001&lt;/code&gt; .&lt;/p&gt;
&lt;p&gt;IP地址分为不同类的地址用于不同的功能。在早期互联网中，根据地址量分为&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A类地址 -- 首位范围1~126(二进首位为0)，共有 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mn&gt;24&lt;/mn&gt;&lt;/msup&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;2^{24}-2&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8974em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;24&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 个地址，默认为&lt;code&gt;/8&lt;/code&gt; 子网&lt;/li&gt;
&lt;li&gt;B类地址 -- 首位范围128~191(二进首位为1)，共有 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mn&gt;16&lt;/mn&gt;&lt;/msup&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;2^{16}-1&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8974em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;16&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 个地址，默认为&lt;code&gt;/16&lt;/code&gt;子网&lt;/li&gt;
&lt;li&gt;C类地址 -- 首位地址192~223(前两位为1)， 共 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mn&gt;8&lt;/mn&gt;&lt;/msup&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;2^8-1&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8974em;vertical-align:-0.0833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;8&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 个地址，默认为&lt;code&gt;/24&lt;/code&gt;子网&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;其中部分特殊的地址不能作为普通主机的地址，如&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;127.x.x.x&lt;/code&gt; 作为本机的回环地址，比如&lt;code&gt;127.0.0.1&lt;/code&gt;作为本机的地址，但是它直接指向系统内核，而不指向某个网卡，因此不能ARP也没有MAC地址。不同的进程可以监听不同的本机回环地址，比如进程A可以监听&lt;code&gt;127.0.0.1:8080&lt;/code&gt;, 进程B可以监听&lt;code&gt;127.0.0.2:8080&lt;/code&gt;而不发生冲突&lt;/li&gt;
&lt;li&gt;主机号全为0，比如在&lt;code&gt;192.168.0.1/16&lt;/code&gt; 网络下的&lt;code&gt;192.168.0.0&lt;/code&gt; 表示本网络本身&lt;/li&gt;
&lt;li&gt;主机号全为1，比如在&lt;code&gt;192.168.0.1/16&lt;/code&gt; 网络下的&lt;code&gt;192.168.255.255&lt;/code&gt; 表示本网络的广播地址&lt;/li&gt;
&lt;li&gt;32位全为1，当前计算机可达广播域的受限广播&lt;/li&gt;
&lt;li&gt;32为全为0，表示本网络的本主机&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;多播地址不能作为源地址，但是能作为目的地址。多播地址是IPV4 D类地址，前四位为&lt;code&gt;1110&lt;/code&gt;,即首位地址范围为224~239&lt;/p&gt;
&lt;p&gt;在CIDR出现后，每8位间隔之间可以拆分，因此可以形成不同的子网规则。同时C类地址结尾为0的主机地址也变得可用。&lt;/p&gt;
&lt;p&gt;子网掩码是一串&lt;code&gt;1&lt;/code&gt;与一串&lt;code&gt;0&lt;/code&gt;构成的二进制码。&lt;code&gt;1&lt;/code&gt; 作为masked，将子网构建的共同ip段&amp;quot;掩盖&amp;quot;, 其原理是子网掩码与IP地址逐位与运算。未被masked的IP地址段作为子网段的可变部分，处于这个部分的IP地址同属一个子网。&lt;/p&gt;
&lt;p&gt;比如对子网掩码&lt;code&gt;255.255.255.0&lt;/code&gt;，局域网的&lt;code&gt;192.168.0.x&lt;/code&gt; 同属一个子网中。&lt;/p&gt;
&lt;p&gt;CIDR的十进制整数表示实际就是将子网掩码的&lt;code&gt;1&lt;/code&gt;的数量使用整数记号表示。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;为什么要划分子网&lt;/strong&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;地址空间利用率低&lt;/li&gt;
&lt;li&gt;路由表过大&lt;/li&gt;
&lt;li&gt;地址分配缺乏灵活性&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;路由聚合&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#路由聚合&#34;&gt;#&lt;/a&gt; 路由聚合&lt;/h3&gt;
&lt;p&gt;路由器能将CIDR分割的若干个子网进行子网，用一条聚合路由代替聚合的子网。&lt;/p&gt;
&lt;p&gt;聚合的规则满足&lt;strong&gt;最长前缀匹配&lt;/strong&gt;，如果一个主机满足若干个CIDR规则，它将匹配最长的前缀。&lt;/p&gt;
&lt;p&gt;路由聚合方式可以仿照二叉树处理。对每一位进行二分染色，比如&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;        /26&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;        /  \&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;/27    0    1&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;      / \  / \&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;/28  0  1  0  1&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;考虑三个子网聚合，但是不涉及更低级的情况，就只有27位0与28位为0/1三个子网合并或者27位1与28位0/1三个子网聚合的方式。&lt;/p&gt;
&lt;h3 id=&#34;网络地址转换-nat&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#网络地址转换-nat&#34;&gt;#&lt;/a&gt; 网络地址转换 NAT&lt;/h3&gt;
&lt;p&gt;路由器将局域网私有地址与公网IP地址进行映射，并对外隐藏局域网内部的结构。&lt;/p&gt;
&lt;p&gt;局域网有三个私有地址块&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;10.0.0.0/8&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;172.16.0.0/12&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;192.168.0.0/16&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;互联网路由一律丢弃目的地址为私有地址的数据报。&lt;/p&gt;
&lt;p&gt;路由器在进行NAT的时候，将源地址从发送主机的局域网地址更改为路由器的公网地址，再封装为MAC帧发送。&lt;/p&gt;
&lt;h3 id=&#34;arp协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#arp协议&#34;&gt;#&lt;/a&gt; ARP协议&lt;/h3&gt;
&lt;p&gt;主机与路由器都更加ARP协议，通过IP地址确定对应硬件的MAC地址。ARP只能向广播域内的设备发送ARP请求以获取MAC地址，获取MAC地址后动态维护一个ARP表，每隔一段时间更新。&lt;/p&gt;
&lt;p&gt;在跨网段通信时，ARP通常解析的是下一跳的路由器MAC地址。因为根据MAC帧的定义，MAC帧维护的都是每一跳的信息，每一个路由器重新封装IP帧进入MAC帧。&lt;/p&gt;
&lt;h3 id=&#34;dhcp协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#dhcp协议&#34;&gt;#&lt;/a&gt; DHCP协议&lt;/h3&gt;
&lt;p&gt;DHCP是局域网内动态分配IP地址的方式，提供了即插即用的联网机制。现在的局域网有线/无线连接均不需要手动进行IP地址设置，这正是DHCP的功能体现。&lt;/p&gt;
&lt;p&gt;DHCP协议是基于UDP协议的，因为UDP协议无需建立连接，且支持广播&lt;/p&gt;
&lt;p&gt;DHCP基于&lt;strong&gt;客户/服务器模型&lt;/strong&gt;，主机向DHCP服务器发送&lt;strong&gt;发现报文&lt;/strong&gt;时作为DHCP客户全体广播，但是只有DHCP能响应。如果数据库中有该设备的配置信息，则返回相应的信息；否则就从IP池中取一个地址分配。&lt;/p&gt;
&lt;p&gt;交换流程为：&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;主机广播&amp;quot;DHCP Discover&amp;quot; 报文，源地址为&lt;code&gt;0.0.0.0&lt;/code&gt;作为本机，目的地址为&lt;code&gt;255.255.255.255&lt;/code&gt;作为广播域内受限广播地址。&lt;/li&gt;
&lt;li&gt;DHCP服务器收到后，返回&amp;quot;DHCP Offer&amp;quot;，包含IP地址、子网掩码、DNS服务器、租用时间等。DHCP Offer帧的源地址为当前DHCP服务器地址，目的地址为&lt;code&gt;255.255.255.255&lt;/code&gt;受限广播地址&lt;/li&gt;
&lt;li&gt;主机收到多个DHCP Offer后选择其中一个IP地址设置，广播发送&lt;code&gt;DHCP Request&lt;/code&gt;请求报文申请IP地址。其他的服务器接收到后释放&lt;code&gt;DHCP Offer&lt;/code&gt;分配的IP&lt;/li&gt;
&lt;li&gt;被选中的DHCP服务器返回&lt;code&gt;DHCP ACK&lt;/code&gt;确认报文，仍然以广播形式发布，DHCP客户收到后配置生效&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;DHCP客户会根据租约时间进行IP续租。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;租期过 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;50&lt;/mn&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;%&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;50\%&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8056em;vertical-align:-0.0556em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;50%&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 时发送请求报文，请求更新租用期，如果DHCP服务器不同意则单播发回DHCP否认报文，客户需要停止并释放当前IP并重新申请。&lt;/li&gt;
&lt;li&gt;租期过 &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mn&gt;87.5&lt;/mn&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;%&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;87.5\%&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8056em;vertical-align:-0.0556em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;87.5%&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 再次申请，如果仍然无响应，则在租用期到后停止使用IP地址并重新申请。&lt;/li&gt;
&lt;li&gt;DHCP客户也可以自动放弃租约，释放IP地址并发送DHCP释放报文。&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;icmp协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#icmp协议&#34;&gt;#&lt;/a&gt; ICMP协议&lt;/h3&gt;
&lt;p&gt;ICMP协议(网际控制报文协议)用于向主机或者路由器报告传输中的差错与异常，分为ICMP差错报告报文与ICMP询问报文&lt;/p&gt;
&lt;p&gt;ICMP差错报告报文:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;终点不可达 -- 路由器/主机无法交付数据报，向远点发送终点不可达报文。比如无法寻找或到达目标网络，或者目标主机端口不开放&lt;/li&gt;
&lt;li&gt;时间超过 -- 跳转耗尽TTL时间，或者在一定时间内目的主机未收齐某个数据报的所有分组&lt;/li&gt;
&lt;li&gt;参数问题&lt;/li&gt;
&lt;li&gt;重定向&lt;/li&gt;
&lt;li&gt;源点抑制 -- 路由器或者主机拥塞导致数据报丢失&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;ICMP询问报文:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;回送请求和回答报文&lt;/li&gt;
&lt;li&gt;时间戳请求和回答报文&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;ipv6地址&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ipv6地址&#34;&gt;#&lt;/a&gt; IPV6地址&lt;/h2&gt;
&lt;p&gt;IPV6的IP地址是128位二进制值，展示为8组、每组4位十六进制数。&lt;/p&gt;
&lt;p&gt;IPV6 有两种缩写的方式&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;省略先导0&lt;/li&gt;
&lt;li&gt;缩写中间0 -- 只有一个连续0组可以简写，如果出现两个连续0的片段，只能缩写其中一个段，不然无法准确确定0 的个数，通过&lt;code&gt;&amp;lt;&amp;gt;::&amp;lt;&amp;gt;&lt;/code&gt;缩写替换的0段&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;根据传输方式分为&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;单播 -- 点对点传播&lt;/li&gt;
&lt;li&gt;多播 -- 一对多传播，目的ip为多播组&lt;/li&gt;
&lt;li&gt;任播 -- 发送到路由距离最近的节点&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;IPV6不支持广播&lt;/p&gt;
&lt;h3 id=&#34;ipv6-地址分类&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ipv6-地址分类&#34;&gt;#&lt;/a&gt; IPV6 地址分类&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;未指明地址 -- &lt;code&gt;::/128&lt;/code&gt; 全为0 的地址段，表明当前设备还未分配一个IP地址&lt;/li&gt;
&lt;li&gt;环回地址 -- &lt;code&gt;::1/128&lt;/code&gt; 类似于 &lt;code&gt;127.x.x.x&lt;/code&gt;, 但是IPV6只分配一个IP地址，不同于IPV4直接分配一个网段&lt;/li&gt;
&lt;li&gt;多播地址 -- &lt;code&gt;FF00::/8&lt;/code&gt; 前8为均为1，后面可变的子网。&lt;/li&gt;
&lt;li&gt;本地链路单播地址 -- &lt;code&gt;FE80::/10&lt;/code&gt; 本地链路的单播地址，不会被路由器转发&lt;/li&gt;
&lt;li&gt;全球单播地址 -- 分为三段地址 -- 全球路由选择前缀、子网标识符、接口标识符，全球路由选择前缀不分配时，子网标识符作为完整前缀。&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;路由算法与路由协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#路由算法与路由协议&#34;&gt;#&lt;/a&gt; 路由算法与路由协议&lt;/h1&gt;
&lt;p&gt;路由算法与路由协议刻画的是路由器如何管理传输报文的转发的方式。宏观上可以分为:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;局域网内的转发协议与算法(内部网关协议IGP) -- 如 RIP/OSPF&lt;/li&gt;
&lt;li&gt;以太网网间的转发(外部网关协议EGP) -- 如BGP-4&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;路由算法&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#路由算法&#34;&gt;#&lt;/a&gt; 路由算法&lt;/h2&gt;
&lt;p&gt;路由算法分为静态路由算法与动态路由算法&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;静态路由 -- 网络管理员手动配置路由表，实现简单、开销小，但是无法动态调整网络变化&lt;/li&gt;
&lt;li&gt;动态路由 -- 根据网络状态动态调整自身路由表，实现复杂、开销大，但是能更好的适应网络的变化&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;距离向量算法&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#距离向量算法&#34;&gt;#&lt;/a&gt; 距离向量算法&lt;/h3&gt;
&lt;p&gt;距离-向量算法基于Bellman-Ford 算法 &lt;a href=&#34;/2026/04/12/CS/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84/%E5%9B%BE/&#34; title=&#34;图&#34;&gt;图&lt;/a&gt;，通过根据相邻节点的距离表的最小值更新当前节点的距离表的值。&lt;/p&gt;
&lt;p&gt;距离-向量算法主要应用于内部网关协议的RIP协议中。&lt;/p&gt;
&lt;h4 id=&#34;rip协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#rip协议&#34;&gt;#&lt;/a&gt; RIP协议&lt;/h4&gt;
&lt;p&gt;RIP使用&amp;quot;跳数&amp;quot; -- 即图距离表示到达距离的远近，&lt;strong&gt;好&lt;/strong&gt;的路径表示经历的跳数较少。&lt;/p&gt;
&lt;p&gt;RIP的交换报文结构为&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;&amp;#x3C;目的网络N,距离d， 下一跳的路由地址X&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;报文只与相邻的路由器进行交换，直接交换&lt;strong&gt;完整的本地路由表&lt;/strong&gt;，每隔固定的时间间隔进行交换(默认30s)&lt;/p&gt;
&lt;p&gt;由于可能出现&lt;strong&gt;无穷计数问题&lt;/strong&gt;，RIP规定最大跳的计数小于16，大于等于16的跳数表示为网络不可达&lt;/p&gt;
&lt;p&gt;距离向量算法与RIP协议会遇到&lt;strong&gt;无穷计数问题&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;考虑路由结构&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;A-B-C&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;某一时刻&lt;code&gt;B-C&lt;/code&gt;链路中断，但是B仍然能通过A路由表更新到C的路径，A仍能通过B路由表更新到C的路径，两个路由表一直+1直到无穷。这样的问题就是无穷计数问题。RIP协议为了规避这样的情况，设定了最大跳数为16，路由距离到达16时发生中断，在无穷增加的中途截断。&lt;/p&gt;
&lt;p&gt;RIP的优点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;实现简单、开销较小&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;好消息传得快&lt;/strong&gt; -- 路径短的路由信息能快速传播&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;RIP的缺点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;限制了网络规模&lt;/li&gt;
&lt;li&gt;路由间交换的是每一个路由的完整路由表，网络通信的开销较大&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;坏消息传的慢&lt;/strong&gt; -- 慢收敛，网络故障需要传递多次才能收敛（因为更好的网络路径可以直接更新，更坏的网络路径依赖路由间的路由表自加更新）&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;RIP是应用层的路由器协议，基于&lt;strong&gt;UDP协议&lt;/strong&gt;实现，报文通过520端口向相邻路由广播&lt;/p&gt;
&lt;h3 id=&#34;链路状态算法&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#链路状态算法&#34;&gt;#&lt;/a&gt; 链路状态算法&lt;/h3&gt;
&lt;p&gt;链路状态算法基于广泛共享整个广播域的连接状态表以构建完整的网络拓扑关系。每一个路由节点都主动探索所有的相邻节点，且定时将自己的路由表信息泛洪到整个全网的所有节点中。&lt;/p&gt;
&lt;p&gt;由于每一个路由都有全网链路状态表，路由可以通过Dijkstra算法实现最短路径的计算&lt;/p&gt;
&lt;h4 id=&#34;ospf协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ospf协议&#34;&gt;#&lt;/a&gt; OSPF协议&lt;/h4&gt;
&lt;p&gt;OSPF协议基于链路状态算法，通过洪泛法向自治系统内的所有路由器发送信息：向相邻路由发送，相邻的路由再转发给这个路由的邻居路由，已实现自治系统内所有路由都接收到洪泛的路由表信息。&lt;/p&gt;
&lt;p&gt;OSPF发送的是局部的路由表信息，本路由与相邻路由之间的链路信息。每一个路由器根据洪泛的局部路由信息拼接成一张完整的全LS路由拓扑表(构建为&lt;strong&gt;链路状态数据库(LSDB)&lt;/strong&gt;)，再通过Dijkstra算法得到最短路径。&lt;/p&gt;
&lt;p&gt;OSPF在路由拓扑状态更新时才发送洪泛，而RIP是定时更新路由表信息。而且OSPF能单次洪泛就拼出完整的路由拓扑信息，因此不会出现类似RIP的”&lt;strong&gt;坏消息传的慢&lt;/strong&gt;“问题&lt;/p&gt;
&lt;p&gt;OSPF是网络层协议，直接将路由表封装IP报文中传输（协议字段为89，既不是TCP也不是UDP）&lt;/p&gt;
&lt;p&gt;OSPF可以将每一个自治系统细分为更小的洪泛区域，一个自治系统中有一个主干区域与若干区域构成，主干区域有一个或多个区域边界路由与外界自治系统通信，每一个分区也有一个或多个区域边界路由用于连通区域。&lt;/p&gt;
&lt;h5 id=&#34;ospf的五种分组类型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ospf的五种分组类型&#34;&gt;#&lt;/a&gt; OSPF的五种分组类型&lt;/h5&gt;
&lt;ul&gt;
&lt;li&gt;问候分组(Hello)分组： 发现邻居路由并维持邻接关系，确认相邻路由链路的双向连通性&lt;/li&gt;
&lt;li&gt;数据库描述(DD)分组： 向邻居发送自己的LSDB信息的摘要信息&lt;/li&gt;
&lt;li&gt;链路状态请求(LSR)分组: 向邻居索取某些链路状态项目的详细信息&lt;/li&gt;
&lt;li&gt;链路状态更新(LSU)分组： 洪泛链路状态通告&lt;/li&gt;
&lt;li&gt;链路状态确认(LSAck)分组： 对链路状态进行确认&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 id=&#34;bgp-边界网关协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#bgp-边界网关协议&#34;&gt;#&lt;/a&gt; BGP 边界网关协议&lt;/h3&gt;
&lt;p&gt;边界网关协议用于建立自治系统之间的路由表信息交换, 属于外部网关协议。&lt;/p&gt;
&lt;p&gt;BGP需要考虑不同AS内网关协议的兼容性与合法性、政治、经济等因素。因此BGP通常只考虑可达性与相对较好路由链路，而不是选择最佳路由。&lt;/p&gt;
&lt;h4 id=&#34;路径向量路由选择协议&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#路径向量路由选择协议&#34;&gt;#&lt;/a&gt; 路径向量路由选择协议&lt;/h4&gt;
&lt;p&gt;BGP路由报文包括&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-text&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;&amp;#x3C;前缀，AS-PATH,NEXT-HOP&gt;&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;p&gt;&lt;code&gt;AS-PATH&lt;/code&gt;表示经过的自治系统序列&lt;br /&gt;
&lt;code&gt;NEXT-HOP&lt;/code&gt;表示去往目的网络的BGP路由的下一跳地址&lt;/p&gt;
&lt;p&gt;BGP在AS内需要建立&lt;code&gt;iBGP&lt;/code&gt;会话，保证BGP报文在AS内部路由中传输。通过&lt;code&gt;eBGP&lt;/code&gt;会话在边界路由间传输BPG报文。BGP报文在路由间都通过179端口建立半永久TCP连接以交换BGP路由信息。&lt;/p&gt;
&lt;p&gt;AS内的路由器如果存在跨域通信的需求，也会解析&lt;code&gt;iBGP&lt;/code&gt;并更新自己的路由表&lt;/p&gt;
&lt;p&gt;路由选择的方式有&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;首选本地偏好值最高的策略 -- 管理员手动设置偏好值，偏好值高的优先&lt;/li&gt;
&lt;li&gt;选择AS跳数最少 -- 偏好值相同时，根据经过的AS最短转发。AS跳数最短不一定为路由跳数最少，因此AS跳数最少的路由路径不一定是最优的路径&lt;/li&gt;
&lt;li&gt;热土豆路由选择算法 -- 基于AS内实现转发逻辑。如果当前AS有多个可达目的网络的边缘网关，则本AS的转发基于本AS内最优的原则，在本AS选择经过路由最少的路径。&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;bgp报文&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#bgp报文&#34;&gt;#&lt;/a&gt; BGP报文&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;Open报文 -- 建立BGP会话与通信初始化&lt;/li&gt;
&lt;li&gt;Update报文 -- 通告路由信息，并列出撤销的多条路由&lt;/li&gt;
&lt;li&gt;Keepaliv报文 -- 用于确定对等路由的链路连通性，默认间隔为60s&lt;/li&gt;
&lt;li&gt;Notification报文 -- 检测差错&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 id=&#34;ip-多播&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ip-多播&#34;&gt;#&lt;/a&gt; IP 多播&lt;/h1&gt;
&lt;p&gt;IP多播是指一个发送端的发送报文可以由多个接收端接收。多播只发送一个分组，经过分叉节点才进行复制与转发，加入多播组的主机可以接收该分组。多播机制降低了服务器的负载和网络负载。&lt;/p&gt;
&lt;p&gt;IPV4的多播地址为D类地址。即首位&lt;code&gt;224~239&lt;/code&gt;，二进前四位为1110的IPV4地址，因此总地址量为&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mrow&gt;&lt;mn&gt;32&lt;/mn&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;4&lt;/mn&gt;&lt;/mrow&gt;&lt;/msup&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;msup&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mn&gt;28&lt;/mn&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;2^{32-4} = 2^{28}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;32&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;4&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;28&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;个&lt;/p&gt;
&lt;p&gt;多播数据报是尽最大努力交付，不提供可靠服务，也不产生ICMP的接收报文。同时，多播只能为目的地址而不能为源地址，因为单次报文的发送只能有一个源设备。&lt;/p&gt;
&lt;h2 id=&#34;ip-多播将ip地址映射为mac地址&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#ip-多播将ip地址映射为mac地址&#34;&gt;#&lt;/a&gt; IP 多播将IP地址映射为MAC地址&lt;/h2&gt;
&lt;p&gt;D类的地址的前4位为固定的&lt;code&gt;1110&lt;/code&gt;, 四位后的连续五位不映射为MAC地址，而是作为多对一的映射编码，后23位直接映射到MAC地址的后23位。48位MAC地址的前25位为固定编码。&lt;/p&gt;
&lt;p&gt;由于后五位的映射编码，一个MAC地址能对应&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mn&gt;2&lt;/mn&gt;&lt;mn&gt;5&lt;/mn&gt;&lt;/msup&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mn&gt;32&lt;/mn&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;2^5=32&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;2&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;5&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;32&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;个IP地址以实现IP的多播。&lt;/p&gt;

 &lt;link rel=&#34;stylesheet&#34; type=&#34;text/css&#34; href=&#34;https://cdn.jsdelivr.net/hint.css/2.4.1/hint.min.css&#34;&gt;&lt;h1 id=&#34;encoder-decoder-structures-in-machine-learning-using-information-measures&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#encoder-decoder-structures-in-machine-learning-using-information-measures&#34;&gt;#&lt;/a&gt; Encoder-Decoder Structures in Machine Learning Using Information Measures&lt;/h1&gt;
&lt;p&gt;本文主要展示的是如何通过信息度量(在本文中使用的是互信息度量) 经历 Encoder 后的信息变化&lt;/p&gt;
&lt;h2 id=&#34;基本数学量定义&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基本数学量定义&#34;&gt;#&lt;/a&gt; 基本数学量定义&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;最小错误概率 Minimum Probability of Error&lt;/strong&gt; 用于刻画对于一个预测任务关系&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mo&gt;:&lt;/mo&gt;&lt;mi&gt;X&lt;/mi&gt;&lt;mo&gt;→&lt;/mo&gt;&lt;mi&gt;Y&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;r: X\to Y&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4306em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;:&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.07847em;&#34;&gt;X&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;→&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.6833em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.22222em;&#34;&gt;Y&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 的预测损失。&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;script&#34;&gt;F&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;X&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;Y&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\mathcal{F}(X,Y)&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathcal&#34; style=&#34;margin-right:0.09931em;&#34;&gt;F&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.07847em;&#34;&gt;X&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.22222em;&#34;&gt;Y&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 表示预测映射集。 最小错误概率定义为&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;ℓ&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;μ&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;X&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;Y&lt;/mi&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo&gt;:&lt;/mo&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;munder&gt;&lt;mrow&gt;&lt;mi&gt;min&lt;/mi&gt;&lt;mo&gt;⁡&lt;/mo&gt;&lt;/mrow&gt;&lt;mrow&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mo&gt;∈&lt;/mo&gt;&lt;mi mathvariant=&#34;script&#34;&gt;F&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;X&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;Y&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;/munder&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;ℓ&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\ell (\mu_{X,Y}) := \min_{r\in \mathcal{F}(X,Y)} \ell (r)
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0361em;vertical-align:-0.2861em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;ℓ&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;μ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3283em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.07847em;&#34;&gt;X&lt;/span&gt;&lt;span class=&#34;mpunct mtight&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.22222em;&#34;&gt;Y&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2861em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;:=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.716em;vertical-align:-0.966em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop op-limits&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6679em;&#34;&gt;&lt;span style=&#34;top:-2.309em;margin-left:0em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mrel mtight&#34;&gt;∈&lt;/span&gt;&lt;span class=&#34;mord mathcal mtight&#34; style=&#34;margin-right:0.09931em;&#34;&gt;F&lt;/span&gt;&lt;span class=&#34;mopen mtight&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.07847em;&#34;&gt;X&lt;/span&gt;&lt;span class=&#34;mpunct mtight&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.22222em;&#34;&gt;Y&lt;/span&gt;&lt;span class=&#34;mclose mtight&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span&gt;&lt;span class=&#34;mop&#34;&gt;min&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.966em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;ℓ&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;其中&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex-display&#34;&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34; display=&#34;block&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;ℓ&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo&gt;:&lt;/mo&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;p&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;X&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo mathvariant=&#34;normal&#34;&gt;≠&lt;/mo&gt;&lt;mi&gt;Y&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;μ&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;X&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;Y&lt;/mi&gt;&lt;/mrow&gt;&lt;/msub&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mrow&gt;&lt;mo fence=&#34;true&#34;&gt;{&lt;/mo&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;∣&lt;/mi&gt;&lt;mi&gt;r&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo mathvariant=&#34;normal&#34;&gt;≠&lt;/mo&gt;&lt;mi&gt;y&lt;/mi&gt;&lt;mo fence=&#34;true&#34;&gt;}&lt;/mo&gt;&lt;/mrow&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\ell(r) := p(r(X)\neq Y) =\mu_{X,Y} (\left\{(x,y)|r(x)\neq y\right\})
&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;ℓ&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;:=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;p&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.07847em;&#34;&gt;X&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;&lt;span class=&#34;mrel&#34;&gt;&lt;span class=&#34;mord vbox&#34;&gt;&lt;span class=&#34;thinbox&#34;&gt;&lt;span class=&#34;rlap&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8889em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;inner&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mrel&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;fix&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.22222em;&#34;&gt;Y&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0361em;vertical-align:-0.2861em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;μ&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3283em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.07847em;&#34;&gt;X&lt;/span&gt;&lt;span class=&#34;mpunct mtight&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.22222em;&#34;&gt;Y&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2861em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;minner&#34;&gt;&lt;span class=&#34;mopen delimcenter&#34; style=&#34;top:0em;&#34;&gt;{&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.02778em;&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;&lt;span class=&#34;mrel&#34;&gt;&lt;span class=&#34;mord vbox&#34;&gt;&lt;span class=&#34;thinbox&#34;&gt;&lt;span class=&#34;rlap&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8889em;vertical-align:-0.1944em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;inner&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mrel&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;fix&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;y&lt;/span&gt;&lt;span class=&#34;mclose delimcenter&#34; style=&#34;top:0em;&#34;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;即预测映射中预测效果最优的预测映射的错误概率&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;互信息 Mutual Information&lt;/strong&gt;&lt;/p&gt;
